CREATE OR REPLACE FUNCTION finance.region_filter(region_col STRING)
RETURN
  IS_ACCOUNT_GROUP_MEMBER('payroll_admin')
  OR region_col = current_user_region();

ALTER TABLE finance.employee_comp
SET ROW FILTER finance.region_filter ON (region);

CREATE OR REPLACE FUNCTION finance.mask_ssn(ssn STRING)
RETURN
  CASE WHEN IS_ACCOUNT_GROUP_MEMBER('payroll_admin')
       THEN ssn
       ELSE 'XXX-XX-' || RIGHT(ssn, 4)
  END;

ALTER TABLE finance.employee_comp
ALTER COLUMN ssn SET MASK finance.mask_ssn;

CREATE VIEW finance.employee_comp_ds_sample AS
SELECT * FROM finance.employee_comp
TABLESAMPLE (10 PERCENT);

GRANT SELECT ON VIEW finance.employee_comp_ds_sample TO `data_scientists`;
GRANT SELECT ON TABLE finance.employee_comp TO `regional_controllers`, `payroll_admin`;

