CREATE TABLE sensor_readings (
  device_id STRING,
  reading_ts TIMESTAMP,
  reading_date DATE,
  metric_type STRING,
  value DOUBLE
)
USING DELTA
PARTITIONED BY (reading_date)
CLUSTER BY (device_id);

-- Weekly maintenance
OPTIMIZE sensor_readings
  WHERE reading_date >= current_date() - INTERVAL 7 DAYS;

VACUUM sensor_readings RETAIN 168 HOURS;

ALTER TABLE sensor_readings
  SET TBLPROPERTIES ('delta.deletedFileRetentionDuration' = '168 hours');

