@dlt.table(name="silver_orders_quarantine")
def silver_orders_quarantine():
    return (
        dlt.read_stream("bronze_orders")
        .filter(
            (col("order_amount") <= 0) |
            col("customer_id").isNull() |
            (col("order_date") > col("_ingest_ts"))
        )
    )

